except BaseException:
    # We were cancelled (e.g. KeyboardInterrupt propagated as a
    # CancelledError into this coroutine) or one job raised. Cancel any
    # still-running jobs and wait for them so their cleanup code runs.
    for t in running:
        t.cancel()
    # Wait for every task to finish its cancellation/cleanup, retrying if
    # a further cancellation is directed at us so that we never leave a
    # job's cleanup half-finished.
    while True:
        try:
            await asyncio.gather(*running, return_exceptions=True)
            break
        except asyncio.CancelledError:
            continue
    raise

